  function renderContextualScreens(scene, current, lang, text) {
    var context = (CONTEXT_SCREEN_TEXT[lang] || CONTEXT_SCREEN_TEXT.en)[current.id];
    var common = text.common, labels = GUIDE_LABELS[lang] || GUIDE_LABELS.en;
    var english = scene[lang] ? "" : common.english;
    var punctuation = lang === "ja" || lang.indexOf("zh_") === 0 ? "。" : ".";
    var primaryCaption = common.example + " " + context.primaryPurpose + punctuation + " " + common.collector + (english ? " " + english : "");
    var detailCaption = context.detailCaption + (english ? " " + english : "");
    function figure(shot, purpose, caption, kind) {
      var dimensions = shot.width && shot.height ? ' width="' + shot.width + '" height="' + shot.height + '"' : '';
      var alt = common.heading + ": " + purpose + (english ? " " + english : "");
      return '<figure class="usecase-screenshot screenshot-' + kind + '"><a href="' + shot.src + '" target="_blank" rel="noopener" aria-label="' + esc(common.zoom + ': ' + purpose) +
        '"><picture><source type="image/webp" srcset="' + shot.src.replace(/\.png$/, '.webp') + '"><img src="' + shot.src + '"' + dimensions + ' loading="lazy" decoding="async" alt="' + esc(alt) +
        '"></picture></a><figcaption><p>' + esc(caption) + '</p><a class="screenshot-enlarge" href="' + shot.src + '" target="_blank" rel="noopener">' + esc(common.zoom) + ' ↗</a></figcaption></figure>';
    }
    var locale = lang === "ja" ? "ja" : "en";
    return '<section class="section-card usecase-screen" id="extension-screens"><h2>' + esc(common.title.replace('{label}', labels[current.id])) +
      '</h2><h3 class="screenshot-context-title">' + esc(context.primaryTitle) + '</h3>' + figure(scene[lang] || scene[locale], context.primaryPurpose, primaryCaption, 'primary') +
      '<div class="screenshot-details"><h3 class="screenshot-context-title">' + esc(context.detailTitle) + '</h3>' + figure(scene.detail[lang] || scene.detail[locale], text.purposes[current.id], detailCaption, 'secondary') + '</div></section>';
  }

